CREATE POLICY enabled_access_management ON public.account_access AS RESTRICTIVE FOR ALL TO authenticated USING(public.account_enabled(auth.uid())) WITH CHECK(public.account_enabled(auth.uid())); CREATE POLICY enabled_profile_updates ON public.profiles AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.account_enabled(auth.uid())) WITH CHECK(public.account_enabled(auth.uid())); CREATE FUNCTION public.validate_payment_record() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.amount<0 OR NEW.status NOT IN ('paid','processing') OR length(trim(NEW.month))=0 THEN RAISE EXCEPTION 'Invalid payment record'; END IF; RETURN NEW; END $$; CREATE TRIGGER validate_payment_record BEFORE INSERT OR UPDATE ON public.payment_records FOR EACH ROW EXECUTE FUNCTION public.validate_payment_record();